 private SteamSession newSteamSession()throws Exception{org.json.JSONObject profile=SteamResources.assetJson(this,"steam-profile/source-profile.json",1024*1024).getJSONObject("steam");if(profile.getInt("appId")!=Installation.APP_ID||profile.getInt("depotId")!=2052411)throw new IOException("Unsupported Steam profile");return new SteamSession(this,Long.parseUnsignedLong(profile.getString("manifestId")),profile.getLong("installedBytes"));}
