 private java.net.InetAddress lanAddress()throws IOException{android.net.ConnectivityManager network=getSystemService(android.net.ConnectivityManager.class);for(android.net.Network item:network.getAllNetworks()){android.net.NetworkCapabilities caps=network.getNetworkCapabilities(item);android.net.LinkProperties links=network.getLinkProperties(item);if(caps==null||links==null||caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_VPN)||!caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI)&&!caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_ETHERNET))continue;for(android.net.LinkAddress link:links.getLinkAddresses()){java.net.InetAddress address=link.getAddress();if(address instanceof java.net.Inet4Address&&!address.isLoopbackAddress()&&!address.isLinkLocalAddress())return address;}}throw new IOException("No LAN IPv4 address");}
 private void refreshQrLan(){if(qrLan==null)return;try{com.google.zxing.common.BitMatrix matrix=SteamQr.encode(qrChallenge,512);int[] pixels=new int[matrix.getWidth()*matrix.getHeight()];for(int y=0;y<matrix.getHeight();y++)for(int x=0;x<matrix.getWidth();x++)pixels[y*matrix.getWidth()+x]=matrix.get(x,y)?android.graphics.Color.BLACK:android.graphics.Color.WHITE;android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(pixels,matrix.getWidth(),matrix.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);try{ByteArrayOutputStream output=new ByteArrayOutputStream();if(!bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,output))throw new IOException("Cannot encode QR image");qrLan.update(output.toByteArray());}finally{bitmap.recycle();}}catch(Exception invalid){stopQrLan();qrLanError=getString(R.string.setup_qr_lan_unavailable);}}
