 @Override public void estimate(long downloadBytes,long installedBytes){estimatedDownload=downloadBytes>0?downloadBytes:0;if(installedBytes>0)estimatedInstall=installedBytes;changed();}
 @Override public void progress(float value,long compressed,long installed){long now=SystemClock.elapsedRealtime();transfer.update(now,compressed,installed);if(now-lastProgress<200&&value<1)return;lastProgress=now;fraction=Math.max(fraction,(Float.isFinite(value)?Math.max(0,Math.min(1,value)):fraction));done=transfer.received;if(estimatedDownload>0)total=estimatedDownload;changed();}
